58	        locations: error.locations,
59	        path: error.path,
60	      })),
61	    })
62	  }
63	
64	  const result = await graphql({
65	    schema: rootGraphQLSchema,
66	    contextValue: { request },
67	    source: query,
68	    variableValues: variables,
69	    operationName,
