50	  error: ZodError,
51	  prelude?: string
52	): InvalidRequestError {
53	  const issue = error.issues[0]
54	  const pathStr = issue.path.join('.')
55	  const message = `${prelude ? `${prelude}: ` : ''}${issue.message} at key "${pathStr}"`
56	
57	  return new InvalidRequestError(message, error)
