8	export function deepFilterRec<T extends object, K extends keyof T>(
9	  arr: Array<RecObj<T, K>>,
10	  recKey: K,
11	  filterFn: (item: T) => boolean
12	) {
13	  return arr.reduce(
14	    (acc, elem) => {
15	      if (!filterFn(elem)) return acc
16	
17	      if (recKey in elem) {
18	        const newSubitems = deepFilterRec(elem[recKey] as Array<RecObj<T, K>>, recKey, filterFn)
19	        const newElem = { ...elem, [recKey]: newSubitems }
20	
21	        if (newSubitems.length > 0 || filterFn(elem)) acc.push(newElem)
22	      } else {
23	        acc.push(elem)
24	      }
25	
26	      return acc
27	    },
28	    [] as Array<RecObj<T, K>>
29	  )
30	}
