  info: GraphQLResolveInfo,
  obj = {},
  opts = { processArguments: false }
): Record<string, any> {
  const fields = info.fieldNodes
  options.processArguments = opts.processArguments
  return fields.reduce((o, ast) => {
    return flattenAST(ast, info, o)
  }, obj)
